func tableExists(ctx context.Context, conn *sql.Conn, name string) (bool, error) {
	var count int
	if err := conn.QueryRowContext(ctx, `SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?`, name).Scan(&count); err != nil {
		return false, fmt.Errorf("checking table %s: %w", name, err)
	}
	return count > 0, nil
}

func resourcesTableHasCompositeKey(ctx context.Context, conn *sql.Conn) (bool, error) {
	rows, err := conn.QueryContext(ctx, `PRAGMA table_info(resources)`)
	if err != nil {
		return false, fmt.Errorf("reading resources table info: %w", err)
	}
	defer rows.Close()

	pk := map[string]int{}
	for rows.Next() {
		var cid int
		var name, typ string
		var notnull, pkOrder int
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &typ, &notnull, &dflt, &pkOrder); err != nil {
			return false, fmt.Errorf("scanning resources table info: %w", err)
		}
		pk[name] = pkOrder
	}
	if err := rows.Err(); err != nil {
		return false, fmt.Errorf("reading resources table info rows: %w", err)
	}
	return pk["resource_type"] == 1 && pk["id"] == 2, nil
}

func rebuildResourcesFTS(ctx context.Context, conn *sql.Conn) error {
	rows, err := conn.QueryContext(ctx, `SELECT id, resource_type, data FROM resources`)
	if err != nil {
		return fmt.Errorf("querying resources: %w", err)
	}

	type resourceRow struct {
		id           string
		resourceType string
		data         string
	}
	var resources []resourceRow
	for rows.Next() {
		var r resourceRow
		if err := rows.Scan(&r.id, &r.resourceType, &r.data); err != nil {
			_ = rows.Close()
			return fmt.Errorf("scanning resource: %w", err)
		}
		resources = append(resources, r)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return fmt.Errorf("reading resource rows: %w", err)
	}
	if err := rows.Close(); err != nil {
		return fmt.Errorf("closing resource rows: %w", err)
	}

	for _, r := range resources {
		if _, err := conn.ExecContext(ctx,
			`INSERT INTO resources_fts (rowid, id, resource_type, content) VALUES (?, ?, ?, ?)`,
			ftsRowID(r.resourceType, r.id), r.id, r.resourceType, searchableResourceContent(json.RawMessage(r.data)),
		); err != nil {
			return fmt.Errorf("indexing resource %s/%s: %w", r.resourceType, r.id, err)
		}
	}
	return nil
}

const (
	migrationLockTimeout    = 30 * time.Second
	migrationLockBackoffMin = 5 * time.Millisecond
	migrationLockBackoffMax = 100 * time.Millisecond
)

// withMigrationLock runs fn inside a BEGIN IMMEDIATE / COMMIT pair on
// conn, retrying both BEGIN and COMMIT on SQLITE_BUSY against the
// caller-provided deadline. Sharing the deadline with the pre-lock
// version read keeps total Open() latency bounded by a single budget.
// The real upper bound is deadline + one trailing backoff interval
// (≤100ms) + the driver's busy_timeout for the in-flight Exec, since
// the deadline is checked after each failed attempt rather than as a
// hard wall-clock cutoff. fn must use conn (not s.db) so its writes
// participate in the held transaction.
func withMigrationLock(ctx context.Context, conn *sql.Conn, deadline time.Time, fn func() error) error {
	if err := execWithBusyRetry(ctx, conn, "BEGIN IMMEDIATE", "begin migration transaction", deadline); err != nil {
		return err
	}
	committed := false
	defer func() {
		if committed {
			return
		}
		// ROLLBACK uses context.Background() so caller-context cancellation
		// can't strand the connection in an open transaction. A failed
		// rollback is rare on local SQLite (broken file handle, fatal
		// driver error) but worth surfacing — silent swallow leaves a
		// pinned connection returned to the pool with state that will
		// confuse later queries.
		if _, rerr := conn.ExecContext(context.Background(), "ROLLBACK"); rerr != nil {
			fmt.Fprintf(os.Stderr, "warning: store migration rollback failed: %v\n", rerr)
		}
	}()

	if err := fn(); err != nil {
		return err
	}

	if err := execWithBusyRetry(ctx, conn, "COMMIT", "commit migration transaction", deadline); err != nil {
		return err
	}
	committed = true
	return nil
}

// execWithBusyRetry runs stmt on conn and retries on SQLITE_BUSY until
// deadline. It covers BEGIN IMMEDIATE and COMMIT contention;
// modernc.org/sqlite's busy_timeout does not reliably cover either when
// multiple connections race for the WAL write lock.
func execWithBusyRetry(ctx context.Context, conn *sql.Conn, stmt, label string, deadline time.Time) error {
	return retryOnBusy(ctx, deadline, label, func() error {
		_, err := conn.ExecContext(ctx, stmt)
		return err
	})
}

// retryOnBusy runs op and retries it on SQLITE_BUSY/LOCKED until
// deadline. The same retry shape covers Exec, Query, and any other
// SQLite call that can race the WAL writer lock — including the
// pre-lock user_version read, where the WAL initialization race on a
// fresh DB can BUSY a SELECT that should otherwise succeed under WAL
// reader/writer concurrency.
func retryOnBusy(ctx context.Context, deadline time.Time, label string, op func() error) error {
	backoff := migrationLockBackoffMin
	for {
		err := op()
		if err == nil {
			return nil
		}
		if !isSQLiteBusy(err) {
			return fmt.Errorf("%s: %w", label, err)
		}
		if time.Now().After(deadline) {
			// The label carries the operation context (e.g. "begin
			// migration transaction", "reading schema version") — we
			// don't hardcode "waiting for write lock" because pre-lock
			// reads also flow through this helper.
			return fmt.Errorf("%s: timed out after %s under SQLite contention: %w", label, migrationLockTimeout, err)
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("%s: %w", label, ctx.Err())
		case <-time.After(backoff):
		}
		backoff = min(backoff*2, migrationLockBackoffMax)
	}
}

// isSQLiteBusy reports whether err is a retryable SQLite lock condition.
// Covers both the file-level WAL writer race (SQLITE_BUSY / "database is
// locked") and the table-level shared-cache contention (SQLITE_LOCKED /
// "database table is locked"). The match is on the error string because
// modernc.org/sqlite does not export an error type the generated code
// can switch on without dragging the driver package into every store
// consumer.
func isSQLiteBusy(err error) bool {
	if err == nil {
		return false
	}
	msg := err.Error()
	return strings.Contains(msg, "SQLITE_BUSY") ||
		strings.Contains(msg, "SQLITE_LOCKED") ||
		strings.Contains(msg, "database is locked") ||
		strings.Contains(msg, "database table is locked")
}

var historyResourceTypes = map[string]struct{}{
	"catalog":                {},
	"inventory":              {},
	"changes":                {},
	"events":                 {},
	"webhooks":               {},
	"webhooks-subscriptions": {},
}

var squareSecretFieldNames = map[string]struct{}{
	"access-token": {}, "api-key": {}, "authorization": {}, "bearer-token": {},
	"client-secret": {}, "cookie": {}, "oauth-token": {}, "password": {},
	"private-key": {}, "refresh-token": {}, "secret": {}, "secret-key": {},
	"signature": {}, "signature-key": {}, "signing-key": {}, "signing-secret": {},
	"token": {}, "webhook-signature": {}, "x-square-hmacsha256-signature": {},
}

func normalizedSquareSecretField(key string) string {
	return strings.ReplaceAll(strings.ToLower(strings.TrimSpace(key)), "_", "-")
}

func redactSquareSecrets(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		out := make(map[string]any, len(typed))
		for key, child := range typed {
			if _, secret := squareSecretFieldNames[normalizedSquareSecretField(key)]; secret {
				out[key] = "<redacted>"
			} else {
				out[key] = redactSquareSecrets(child)
			}
		}
		return out
	case []any:
		out := make([]any, len(typed))
		for i, child := range typed {
			out[i] = redactSquareSecrets(child)
		}
		return out
	default:
		return typed
	}
}

func redactSubscriptionResource(data json.RawMessage) (json.RawMessage, error) {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	var value any
	if err := decoder.Decode(&value); err != nil {
		return nil, err
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return nil, fmt.Errorf("trailing JSON content")
	}
	redacted, err := json.Marshal(redactSquareSecrets(value))
	if err != nil {
		return nil, err
	}
	return redacted, nil
}

func scrubLegacyWebhookSubscriptionSecrets(ctx context.Context, conn *sql.Conn) error {
	type resourceRow struct {
		id   string
		data string
	}
	rows, err := conn.QueryContext(ctx, `SELECT id, data FROM resources WHERE resource_type = 'webhooks-subscriptions'`)
	if err != nil {
		return err
	}
	var resources []resourceRow
	for rows.Next() {
		var row resourceRow
		if err := rows.Scan(&row.id, &row.data); err != nil {
			_ = rows.Close()
			return err
		}
		resources = append(resources, row)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	type historyRow struct {
		sequence int64
		data     string
	}
	historyRows, err := conn.QueryContext(ctx, `SELECT sequence, data FROM resource_history WHERE resource_type = 'webhooks-subscriptions'`)
	if err != nil {
		return err
	}
	var history []historyRow
	for historyRows.Next() {
		var row historyRow
		if err := historyRows.Scan(&row.sequence, &row.data); err != nil {
			_ = historyRows.Close()
			return err
		}
		history = append(history, row)
	}
	if err := historyRows.Err(); err != nil {
		_ = historyRows.Close()
		return err
	}
	if err := historyRows.Close(); err != nil {
		return err
	}

	for _, row := range resources {
		redacted, err := redactSubscriptionResource(json.RawMessage(row.data))
		if err != nil {
			return fmt.Errorf("redact current subscription %s: %w", row.id, err)
		}
		if _, err := conn.ExecContext(ctx, `UPDATE resources SET data = ?, updated_at = CURRENT_TIMESTAMP WHERE resource_type = 'webhooks-subscriptions' AND id = ?`, string(redacted), row.id); err != nil {
			return err
		}
		rowID := ftsRowID("webhooks-subscriptions", row.id)
		if _, err := conn.ExecContext(ctx, `DELETE FROM resources_fts WHERE rowid = ?`, rowID); err != nil {
			return err
		}
		if _, err := conn.ExecContext(ctx, `INSERT INTO resources_fts (rowid, id, resource_type, content) VALUES (?, ?, 'webhooks-subscriptions', ?)`, rowID, row.id, searchableResourceContent(redacted)); err != nil {
			return err
		}
	}
	for _, row := range history {
		redacted, err := redactSubscriptionResource(json.RawMessage(row.data))
		if err != nil {
			return fmt.Errorf("redact subscription history %d: %w", row.sequence, err)
		}
		if _, err := conn.ExecContext(ctx, `UPDATE resource_history SET data = ? WHERE sequence = ?`, string(redacted), row.sequence); err != nil {
			return err
		}
	}
	return nil
}

// canonicalHistoryJSON makes object key ordering irrelevant when deciding
// whether a newly observed value deserves another history row.
func canonicalHistoryJSON(data json.RawMessage) ([]byte, error) {
	var value any
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.UseNumber()
	if err := decoder.Decode(&value); err != nil {
		return nil, fmt.Errorf("invalid JSON: %w", err)
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return nil, fmt.Errorf("invalid JSON: trailing content")
	}
	canonical, err := json.Marshal(value)
	if err != nil {
		return nil, fmt.Errorf("canonicalize JSON: %w", err)
	}
	return canonical, nil
}

func recordResourceHistoryTx(tx *sql.Tx, resourceType, id string, data json.RawMessage, observedAt string) error {
	if _, tracked := historyResourceTypes[resourceType]; !tracked {
		return nil
	}
	canonical, err := canonicalHistoryJSON(data)
	if err != nil {
		return fmt.Errorf("canonicalize %s/%s history: %w", resourceType, id, err)
	}
	observedTime, err := time.Parse(time.RFC3339Nano, observedAt)
	if err != nil {
		return fmt.Errorf("parse %s/%s observed time: %w", resourceType, id, err)
	}
	cutoffNS := time.Now().UTC().Add(-resourceHistoryRetention).UnixNano()
	var previous []byte
	var previousSequence int64
	var previousObserved time.Time
	err = tx.QueryRow(
		`SELECT sequence, data, observed_at FROM resource_history
		 WHERE resource_type = ? AND resource_id = ?
		 ORDER BY observed_at_ns DESC, sequence DESC LIMIT 1`,
		resourceType, id,
	).Scan(&previousSequence, &previous, &previousObserved)
	if err != nil && err != sql.ErrNoRows {
		return fmt.Errorf("read %s/%s history: %w", resourceType, id, err)
	}
	previousCanonical, previousCanonicalErr := canonicalHistoryJSON(previous)
	equalRecent := err == nil && previousCanonicalErr == nil && bytes.Equal(previousCanonical, canonical) && previousObserved.After(time.Now().UTC().Add(-resourceHistoryRetention))
	if err := compactResourceHistoryTx(tx, resourceType, id, cutoffNS); err != nil {
		return err
	}
	if equalRecent {
		return nil
	}
	if _, err := tx.Exec(
		`INSERT INTO resource_history (resource_type, resource_id, data, observed_at, observed_at_ns)
		 VALUES (?, ?, ?, ?, ?)`,
		resourceType, id, string(canonical), observedAt, observedTime.UnixNano(),
	); err != nil {
		return fmt.Errorf("record %s/%s history: %w", resourceType, id, err)
	}
	return compactResourceHistoryTx(tx, resourceType, id, cutoffNS)
}

func compactResourceHistoryTx(tx *sql.Tx, resourceType, id string, cutoffNS int64) error {
	if _, err := tx.Exec(`DELETE FROM resource_history
		WHERE resource_type = ? AND resource_id = ? AND observed_at_ns < ?`, resourceType, id, cutoffNS); err != nil {
		return fmt.Errorf("expire %s/%s history: %w", resourceType, id, err)
	}
	if _, err := tx.Exec(`DELETE FROM resource_history WHERE sequence IN (
		SELECT sequence FROM resource_history
		WHERE resource_type = ? AND resource_id = ?
		ORDER BY observed_at_ns DESC, sequence DESC LIMIT -1 OFFSET ?
	)`, resourceType, id, resourceHistoryMaxVersions); err != nil {
		return fmt.Errorf("cap %s/%s history: %w", resourceType, id, err)
	}
	return nil
}

// WebhookDelivery is one locally received webhook. Payload has already been
// redacted by the CLI before it reaches the store.
type WebhookDelivery struct {
	ObservationID    int64
	ReceiptID        string
	EventID          string
	EventType        string
	OccurredAt       time.Time
	ReceivedAt       time.Time
	ReceivedAtSource string
	Payload          json.RawMessage
}

// RecordWebhookDelivery appends every receipt, including repeated event IDs.
func (s *Store) RecordWebhookDelivery(delivery WebhookDelivery) (int64, error) {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()
	if delivery.ReceivedAtSource == "" {
		delivery.ReceivedAtSource = "ingest_time_default_now"
	}
	receivedAt := delivery.ReceivedAt.UTC()
	result, err := tx.Exec(`INSERT INTO webhook_deliveries
		(receipt_id, event_id, event_type, occurred_at, received_at, received_at_source, received_at_ns, payload)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		delivery.ReceiptID, delivery.EventID, delivery.EventType, nullableTime(delivery.OccurredAt),
		receivedAt.Format(time.RFC3339Nano), delivery.ReceivedAtSource, receivedAt.UnixNano(), string(delivery.Payload))
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	cutoffNS := time.Now().UTC().Add(-webhookDeliveryRetention).UnixNano()
	if _, err := tx.Exec(`DELETE FROM webhook_deliveries WHERE observation_id IN (
		SELECT observation_id FROM webhook_deliveries WHERE received_at_ns < ?
		ORDER BY received_at_ns, observation_id LIMIT 1000
	)`, cutoffNS); err != nil {
		return 0, err
	}
	if _, err := tx.Exec(`DELETE FROM webhook_deliveries WHERE observation_id IN (
		SELECT observation_id FROM webhook_deliveries
		ORDER BY received_at_ns DESC, observation_id DESC LIMIT 1000 OFFSET ?
	)`, webhookDeliveryMaxRows); err != nil {
		return 0, err
	}
	if err := tx.Commit(); err != nil {
		return 0, err
	}
	return id, nil
}

// CompactResourceHistory repairs timestamp indexes and fully converges global
// retention in 500-row transactions. Per-resource version caps remain in the
// hot upsert path; this global work runs only once per writable store open.
func (s *Store) CompactResourceHistory(ctx context.Context) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	cutoffNS := time.Now().UTC().Add(-resourceHistoryRetention).UnixNano()
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		tx, err := s.db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		repairResult, err := tx.ExecContext(ctx, `UPDATE resource_history
			SET observed_at_ns = CAST((julianday(observed_at) - 2440587.5) * 86400000000000 AS INTEGER)
			WHERE sequence IN (
				SELECT sequence FROM resource_history
				WHERE observed_at_ns IS NULL AND julianday(observed_at) IS NOT NULL LIMIT 500
			)`)
		if err != nil {
			_ = tx.Rollback()
			return err
		}
		deleteResult, err := tx.ExecContext(ctx, `DELETE FROM resource_history WHERE sequence IN (
			SELECT sequence FROM resource_history WHERE observed_at_ns < ? LIMIT 500
		)`, cutoffNS)
		if err != nil {
			_ = tx.Rollback()
			return err
		}
		if err := tx.Commit(); err != nil {
			return err
		}
		repaired, _ := repairResult.RowsAffected()
		deleted, _ := deleteResult.RowsAffected()
		if repaired == 0 && deleted == 0 {
			return nil
		}
	}
}

// CompactWebhookDeliveries fully converges retention in 1,000-row
// transactions. Each batch releases SQLite's writer lock before the next one,
// so a large overdue cleanup cannot monopolize the database in one transaction.
func (s *Store) CompactWebhookDeliveries(ctx context.Context) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	cutoffNS := time.Now().UTC().Add(-webhookDeliveryRetention).UnixNano()
	for {
		if err := ctx.Err(); err != nil {
			return err
		}
		tx, err := s.db.BeginTx(ctx, nil)
		if err != nil {
			return err
		}
		ageResult, err := tx.ExecContext(ctx, `DELETE FROM webhook_deliveries WHERE observation_id IN (
			SELECT observation_id FROM webhook_deliveries WHERE received_at_ns < ?
			ORDER BY received_at_ns, observation_id LIMIT 1000
		)`, cutoffNS)
		if err != nil {
			_ = tx.Rollback()
			return err
		}
		capResult, err := tx.ExecContext(ctx, `DELETE FROM webhook_deliveries WHERE observation_id IN (
			SELECT observation_id FROM webhook_deliveries
			ORDER BY received_at_ns DESC, observation_id DESC LIMIT 1000 OFFSET ?
		)`, webhookDeliveryMaxRows)
		if err != nil {
			_ = tx.Rollback()
			return err
		}
		if err := tx.Commit(); err != nil {
			return err
		}
		ageDeleted, _ := ageResult.RowsAffected()
		capDeleted, _ := capResult.RowsAffected()
		if ageDeleted == 0 && capDeleted == 0 {
			return nil
		}
	}
}

func nullableTime(value time.Time) any {
	if value.IsZero() {
		return nil
	}
	return value.UTC().Format(time.RFC3339Nano)
}

func (s *Store) upsertGenericResourceTx(tx *sql.Tx, resourceType, id string, data json.RawMessage) error {
	if resourceType == "webhooks-subscriptions" {
		redacted, err := redactSubscriptionResource(data)
		if err != nil {
			return fmt.Errorf("redact %s/%s: %w", resourceType, id, err)
		}
		data = redacted
	}
	now := time.Now().UTC().Format(time.RFC3339Nano)
	if err := recordResourceHistoryTx(tx, resourceType, id, data, now); err != nil {
		return err
	}
	_, err := tx.Exec(
		`INSERT INTO resources (id, resource_type, data, synced_at, updated_at)
		 VALUES (?, ?, ?, ?, ?)
		 ON CONFLICT(resource_type, id) DO UPDATE SET data = excluded.data, synced_at = excluded.synced_at, updated_at = excluded.updated_at`,
		id, resourceType, string(data), now, now,
	)
	if err != nil {
		return err
	}

	ftsRowid := ftsRowID(resourceType, id)
	// Use explicit rowid for FTS5 compatibility with modernc.org/sqlite.
	// Standard DELETE WHERE column=? may not work on FTS5 virtual tables.
	if _, err = tx.Exec(`DELETE FROM resources_fts WHERE rowid = ?`, ftsRowid); err != nil {
		fmt.Fprintf(os.Stderr, "warning: FTS index cleanup failed: %v\n", err)
	}

	if _, err = tx.Exec(
		`INSERT INTO resources_fts (rowid, id, resource_type, content)
		 VALUES (?, ?, ?, ?)`,
		ftsRowid, id, resourceType, searchableResourceContent(data),
	); err != nil {
		// FTS insert failure is non-fatal
		fmt.Fprintf(os.Stderr, "warning: FTS index update failed: %v\n", err)
	}

	return nil
}

func (s *Store) Upsert(resourceType, id string, data json.RawMessage) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := s.upsertGenericResourceTx(tx, resourceType, id, data); err != nil {
		return err
	}

	return tx.Commit()
}

// Propagates sql.ErrNoRows on a miss so callers can distinguish absence from
// other scan errors via errors.Is.
func (s *Store) Get(resourceType, id string) (json.RawMessage, error) {
	var data string
	err := s.db.QueryRow(
		`SELECT data FROM resources WHERE resource_type = ? AND id = ?`,
		resourceType, id,
	).Scan(&data)
	if err != nil {
		return nil, err
	}
	return json.RawMessage(data), nil
}

// List returns resources of the given type. A positive limit caps the result
// count; zero or negative means no limit.
func (s *Store) List(resourceType string, limit int) ([]json.RawMessage, error) {
	query := `SELECT data FROM resources WHERE resource_type = ? ORDER BY updated_at DESC`
	args := []any{resourceType}
	if limit > 0 {
		query += ` LIMIT ?`
		args = append(args, limit)
	}
	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var results []json.RawMessage
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return nil, err
		}
		results = append(results, json.RawMessage(data))
	}
	return results, rows.Err()
}

func (s *Store) Search(query string, limit int, resourceTypes ...string) ([]json.RawMessage, error) {
	if limit <= 0 {
		limit = 50
	}
	matchQuery := ftsMatchQuery(query)
	if matchQuery == "" {
		return nil, nil
	}
	resourceType := ""
	if len(resourceTypes) > 0 {
		resourceType = strings.TrimSpace(resourceTypes[0])
	}
	if resourceType != "" {
		rows, err := s.db.Query(
			`SELECT r.data FROM resources r
			 JOIN resources_fts f ON r.id = f.id AND r.resource_type = f.resource_type
			 WHERE resources_fts MATCH ?
			 AND r.resource_type = ?
			 ORDER BY f.rank
			 LIMIT ?`,
			matchQuery, resourceType, limit,
		)
		if err != nil {
			return nil, err
		}
		defer rows.Close()

		var results []json.RawMessage
		for rows.Next() {
			var data string
			if err := rows.Scan(&data); err != nil {
				return nil, err
			}
			results = append(results, json.RawMessage(data))
		}
		return results, rows.Err()
	}
	rows, err := s.db.Query(
		`SELECT r.data FROM resources r
		 JOIN resources_fts f ON r.id = f.id AND r.resource_type = f.resource_type
		 WHERE resources_fts MATCH ?
		 ORDER BY f.rank
		 LIMIT ?`,
		matchQuery, limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var results []json.RawMessage
	for rows.Next() {
		var data string
		if err := rows.Scan(&data); err != nil {
			return nil, err
		}
		results = append(results, json.RawMessage(data))
	}
	return results, rows.Err()
}

func searchableResourceContent(data json.RawMessage) string {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	var value any
	if err := dec.Decode(&value); err != nil {
		return ""
	}
	var parts []string
	collectSearchableStrings(&parts, "", value)
	return strings.Join(parts, " ")
}

func collectSearchableStrings(parts *[]string, key string, value any) {
	switch v := value.(type) {
	case map[string]any:
		for childKey, child := range v {
			collectSearchableStrings(parts, childKey, child)
		}
	case []any:
		for _, child := range v {
			collectSearchableStrings(parts, key, child)
		}
	case string:
		if shouldIndexSearchString(key, v) {
			*parts = append(*parts, strings.TrimSpace(v))
		}
	}
}

func shouldIndexSearchString(key, value string) bool {
	s := strings.TrimSpace(value)
	if len(s) < 2 {
		return false
	}
	if isIdentifierKey(key) {
		return false
	}
	lower := strings.ToLower(s)
	switch {
	case IsUUID(s):
		return false
	case isoDatePattern.MatchString(s):
		return false
	case strings.HasPrefix(lower, "http://") || strings.HasPrefix(lower, "https://"):
		return false
	}
	tokens := ftsQueryTokenRE.FindAllString(s, -1)
	return len(tokens) > 0
}

func isIdentifierKey(key string) bool {
	if key == "" {
		return false
	}
	lower := strings.ToLower(key)
	return lower == "id" ||
		lower == "uuid" ||
		strings.HasSuffix(lower, "_id") ||
		strings.HasSuffix(lower, "-id") ||
		strings.HasSuffix(key, "Id") ||
		strings.HasSuffix(key, "ID")
}

func ftsMatchQuery(query string) string {
	tokens := ftsQueryTokenRE.FindAllString(query, -1)
	if len(tokens) == 0 {
		return ""
	}
	quoted := make([]string, 0, len(tokens))
	for _, token := range tokens {
		quoted = append(quoted, `"`+token+`"`)
	}
	return strings.Join(quoted, " ")
}

func extractObjectID(obj map[string]any) string {
	for _, key := range []string{"id", "Id", "ID", "_id", "uuid", "slug", "name"} {
		if v, ok := obj[key]; ok {
			if id := ResourceIDString(v); id != "" && id != "<nil>" {
				return id
			}
		}
	}
	return ""
}

// ftsRowID derives a deterministic rowid from a string ID for use with FTS5.
// Any change to this derivation requires a StoreSchemaVersion bump and a
// resources_fts rebuild migration for already-stamped databases.
// modernc.org/sqlite's FTS5 implementation may not support DELETE WHERE column=?
// on virtual tables, so we use explicit rowids and DELETE WHERE rowid=? instead.
func ftsRowID(scope, id string) int64 {
	h := fnv.New64a()
	_, _ = h.Write([]byte(scope))
	_, _ = h.Write([]byte{0}) // separator so ("ab","c") != ("a","bc")
	_, _ = h.Write([]byte(id))
	return int64(h.Sum64() & 0x7FFFFFFFFFFFFFFF) // ensure positive
}

// LookupFieldValue resolves a field value from a JSON object map, trying the
// snake_case key first, then the camelCase rendering, then the PascalCase
// rendering. Exported so the sync command's extractID and the upsert path
// resolve fields the same way — a divergence here produces silent drops on
// heterogeneous payloads. The PascalCase pass handles .NET-shaped responses
// (`Id`, `Name`, `OrderId`) without forcing each spec to declare casing.
func LookupFieldValue(obj map[string]any, snakeKey string) any {
	if v, ok := obj[snakeKey]; ok {
		return sqliteFieldValue(v)
	}
	parts := strings.Split(snakeKey, "_")
	for i := 1; i < len(parts); i++ {
		if parts[i] == "" {
			continue
		}
		parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
	}
	camel := strings.Join(parts, "")
	if v, ok := obj[camel]; ok {
		return sqliteFieldValue(v)
	}
	if parts[0] != "" {
		pascal := strings.ToUpper(parts[0][:1]) + parts[0][1:] + strings.Join(parts[1:], "")
		if v, ok := obj[pascal]; ok {
			return sqliteFieldValue(v)
		}
	}
	return nil
}

func sqliteFieldValue(v any) any {
	switch t := v.(type) {
	case nil, string, bool, int, int64, float64, []byte:
		return v
	case json.Number:
		return strings.TrimSpace(t.String())
	default:
		data, err := json.Marshal(v)
		if err != nil {
			return fmt.Sprint(v)
		}
		return string(data)
	}
}

// lookupFieldValue is kept as an unexported alias for in-package callers so
// the existing UpsertBatch code reads naturally without prefixing every call
// with the package name.
func lookupFieldValue(obj map[string]any, snakeKey string) any {
	return LookupFieldValue(obj, snakeKey)
}

// DecodeJSONObject decodes data into an object while preserving JSON numbers.
// Plain json.Unmarshal turns numbers into float64, and fmt on those values can
// render large integer IDs as scientific notation before they reach resources.id.
func DecodeJSONObject(data json.RawMessage) (map[string]any, error) {
	var obj map[string]any
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	if err := dec.Decode(&obj); err != nil {
		return nil, err
	}
	return obj, nil
}

// ResourceIDString returns the stable text form used for resources.id.
func ResourceIDString(v any) string {
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return extendedJSONIDString(t)
	case map[string]any:
		return extendedJSONIDMapString(t)
	case json.Number:
		return strings.TrimSpace(t.String())
	case float64:
		if math.IsNaN(t) || math.IsInf(t, 0) {
			return ""
		}
		return strconv.FormatFloat(t, 'f', -1, 64)
	case float32:
		f := float64(t)
		if math.IsNaN(f) || math.IsInf(f, 0) {
			return ""
		}
		return strconv.FormatFloat(f, 'f', -1, 32)
	default:
		// fmt.Sprint on typed nil pointers returns "<nil>"; callers still guard
		// that sentinel so unresolved IDs do not become stored resource keys.
		return strings.TrimSpace(fmt.Sprint(t))
	}
}

func extendedJSONIDString(value string) string {
	value = strings.TrimSpace(value)
	if !strings.HasPrefix(value, "{") {
		return value
	}
	var object map[string]any
	if err := json.Unmarshal([]byte(value), &object); err != nil {
		return value
	}
	if id := extendedJSONIDMapString(object); id != "" {
		return id
	}
	return value
}

func extendedJSONIDMapString(object map[string]any) string {
	for _, key := range []string{"$oid", "$numberLong", "$numberInt"} {
		if value, ok := object[key]; ok {
			return ResourceIDString(value)
		}
	}
	return ""
}

// upsertApplePayTx writes the per-resource domain-table portion of a
// apple_pay upsert inside an existing transaction. The caller is
// responsible for the generic resources insert (via upsertGenericResourceTx)
// and for committing the tx. Splitting this out lets UpsertBatch dispatch
// domain inserts per item without opening a per-item transaction.
func (s *Store) upsertApplePayTx(tx *sql.Tx, id string, obj map[string]any, data json.RawMessage) error {
	if _, err := tx.Exec(
		`INSERT INTO "apple_pay" ("id", "data", "synced_at", "category", "code", "detail", "field")
		 VALUES (?, ?, ?, ?, ?, ?, ?)
		 ON CONFLICT("id") DO UPDATE SET "data" = excluded."data", "synced_at" = excluded."synced_at", "category" = excluded."category", "code" = excluded."code", "detail" = excluded."detail", "field" = excluded."field"`,
		id,
		string(data),
		time.Now().UTC().Format(time.RFC3339),
		lookupFieldValue(obj, "category"),
		lookupFieldValue(obj, "code"),
		lookupFieldValue(obj, "detail"),
		lookupFieldValue(obj, "field"),
	); err != nil {
		return fmt.Errorf("insert into apple_pay: %w", err)
	}

	return nil
}

// UpsertApplePay inserts or updates a apple_pay record with domain-specific columns.
func (s *Store) UpsertApplePay(data json.RawMessage) error {
	obj, err := DecodeJSONObject(data)
	if err != nil {
		return fmt.Errorf("unmarshaling apple_pay: %w", err)
	}

	id := extractObjectID(obj)
	if id == "" {
		return fmt.Errorf("missing id for apple_pay")
	}
	storageID := resourceStorageID("apple-pay", id, obj)

	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := s.upsertGenericResourceTx(tx, "apple-pay", storageID, data); err != nil {
		return err
	}
	if err := s.upsertApplePayTx(tx, storageID, obj, data); err != nil {
		return err
	}

	return tx.Commit()
}

